The following example demonstrates using Listening with dotConnect for PostgreSQL. You can execute "notify "listen_point"" at the server side to check this code. using System;
using Devart.Data.PostgreSql;
using System.Threading;

namespace ConsoleApplication3 {
        class Program {
                static System.Threading.Timer timer;
                static PgSqlConnection connection;
