The following example demonstrates how to retrieve and manipulate data using . public void UseDataAdapter(PgSqlConnection pgConnection)
{
  PgSqlDataAdapter myAdapter = new PgSqlDataAdapter("SELECT DeptNo, DName FROM Test.Dept", pgConnection);
  myAdapter.MissingSchemaAction = MissingSchemaAction.AddWithKey;
