The example shows how to retrieve several fields at once. Note that only the first three fields are retrieved, though there may be more in the table. public void GetObjects(PgSqlConnection pgConnection)
{
  PgSqlCommand cmd = new PgSqlCommand("SELECT * FROM Test.Emp");
  cmd.Connection = pgConnection;
  pgConnection.Open();
  try
  {
    PgSqlDataReader reader = cmd.ExecuteReader();
    reader.Read();
    object[] objs = new object[3];
    int quant = reader.GetValues(objs);
    for (int i=0;i < quant;i++)
    {
      Console.WriteLine(objs[i]);
    }
    reader.Close();
  }
