The following example creates a PgSqlConnection, a , and a . The example reads through the data, writing it out to the console. Finally, the example closes the , then the PgSqlConnection. public void ReadMyData(string myConnString)
{
  string mySelectQuery = "SELECT DeptNo, DName FROM Test.Dept";
  PgSqlConnection pgConnection = new PgSqlConnection(myConnString);
  PgSqlCommand pgCommand = new PgSqlCommand(mySelectQuery,pgConnection);
  pgConnection.Open();
  PgSqlDataReader pgReader;
  pgReader = pgCommand.ExecuteReader();
  // Always call Read before accessing data.
  while (pgReader.Read()) {
    Console.WriteLine(pgReader.GetInt32(0) + ", " + pgReader.GetString(1));
  }
  // always call Close when done reading.
  pgReader.Close();
  // Close the connection when done with it.
  pgConnection.Close();
} Public Sub ReadMyData(myConnString As String)
  Dim mySelectQuery As String = "SELECT DeptNo, DName FROM Test.Dept"
  Dim pgConnection As New PgSqlConnection(myConnString)
  Dim pgCommand As New PgSqlCommand(mySelectQuery, pgConnection)
  pgConnection.Open()
  Dim pgReader As PgSqlDataReader
  pgReader = pgCommand.ExecuteReader()
  ' Always call Read before accessing data.
  While pgReader.Read()
    Console.WriteLine(pgReader.GetInt32(0).ToString() + ", " _
      + pgReader.GetString(1))
  End While
  ' always call Close when done reading.
  pgReader.Close()
  ' Close the connection when done with it.
  pgConnection.Close()
End Sub

This sample shows how to find out how many rows have been affected during last query. You can do it even if the  has been closed. public void ProcessReader (PgSqlDataReader pgReader)
{
  if (!pgReader.IsClosed)
  {
    while (pgReader.Read())
    {
      for (int i=0;i<pgReader.FieldCount;i++)
      {
        Console.Write("\t"+pgReader[i]);
      }
      Console.WriteLine();
    }
  }
  else
  {
    Console.WriteLine("The DataReader is closed. Rows affected in last action: "+pgReader.RecordsAffected);
  }
} Public Sub ProcessReader(ByVal pgReader As PgSqlDataReader)
  If Not pgReader.IsClosed Then
    Dim i As Integer
    While pgReader.Read()
      For i = 0 To pgReader.FieldCount - 1
        Console.Write(" " & pgReader(i))
      Next i
      Console.WriteLine()
    End While
  Else
    Console.WriteLine("The DataReader is closed. Rows affected in last action: " & pgReader.RecordsAffected)
  End If
End Sub

This sample shows easiness of use of . The sample
creates a  object, passing it SQL query text and connection string, retrieves data from a table and modifies it. Content of the table is printed to console then. Notice that no other component needs to be created by programmer. public void UseDataTable()
{
  PgSqlDataTable myDataTable = new PgSqlDataTable("SELECT * FROM Test.Dept", 
      "host=server;database=test;user id=postgres;");
  try
  {
    myDataTable.FetchAll = true;
        myDataTable.Active = true;
    myDataTable.Rows[3]["DName"] = "Researches";
    Console.WriteLine(myDataTable.Update()+" rows updated.");
    foreach(DataRow myRow in myDataTable.Rows)
    {
      foreach(DataColumn myCol in myDataTable.Columns)
      {
        Console.Write(myRow[myCol]+"\t");
      }
      Console.WriteLine();
    }
  }
  finally
  {
    myDataTable.Active = false;
  }
} Public Sub UseDataTable()
  Dim myDataTable As PgSqlDataTable = New PgSqlDataTable("SELECT * FROM Test.Dept", _
      "host=server;database=test;user id=postgres;")
  Try
    myDataTable.FetchAll = True
        myDataTable.Active = True
    myDataTable.Rows(3)("DName") = "Researches"
    Console.WriteLine(myDataTable.Update() & " rows updated.")
    Dim myRow As DataRow
    Dim myCol As DataColumn
    For Each myRow In myDataTable.Rows
      For Each myCol In myDataTable.Columns
        Console.Write(myRow(myCol) & Chr(9))
      Next myCol
      Console.WriteLine()
    Next myRow
  Finally
    myDataTable.Active = False
  End Try
End Sub

