The following example creates a  and sets some of its properties. Then prepares data and loads it into the table. public void CreateMyLoader()
{
  // Create and open connection
  PgSqlConnection conn = new PgSqlConnection(
      "host=server;database=test;user id=postgres;");
  conn.Open();

  // Create loader instance
  PgSqlLoader loader = new PgSqlLoader("loader_test");
  // Set loader properties
  loader.Connection = conn;
     
  // Prepare for loading
  loader.Open();

  // Set row values
  for (int i = 0; i < 10000; i++) {
    loader.SetValue(0, i);
    loader.SetValue(1, "test string");
    loader.SetValue(2, DateTime.Now);
    // Load next table row
    loader.NextRow();
  }

  // Flush buffer and finish loading
  loader.Close();
