This sample shows how to perform loading of data into a table with the last column set to default value. public void LoadData(PgSqlConnection pgConnection)
{
  pgConnection.Open();
  PgSqlLoader loader = new PgSqlLoader();
  loader.Connection = pgConnection;
  loader.TableName = "load_table";
  try
  {
    loader.CreateColumns();
    //Do not insert data in the last column
    loader.Columns.RemoveAt(loader.Columns.Count-1);
    loader.Open();
    for (int i = 1; i <= 100; i++)
    {
      loader.SetValue("id", i);
      loader.SetValue(1, "test string");
      loader.SetValue("date_field", DateTime.Now);
      loader.NextRow();
    }
    loader.Close();
  }
  finally
  {
    pgConnection.Close();
  }
} Public Sub LoadData(ByVal pgConnection As PgSqlConnection)
  pgConnection.Open()
  Dim loader As PgSqlLoader
  loader = New PgSqlLoader
  loader.Connection = pgConnection
  loader.TableName = "load_table"
  Try
    loader.CreateColumns()
    ' Do not insert data in the last column
    loader.Columns.RemoveAt(loader.Columns.Count - 1)
    loader.Open()
    Dim i As Integer
    For i = 1 To 100
      loader.SetValue("id", i)
      loader.SetValue(1, "test string")
      loader.SetValue("date_field", DateTime.Now)
      loader.NextRow()
    Next i
    loader.Close()
  Finally
    pgConnection.Close()
  End Try
End Sub

