The following example creates a , adds instances of  to the collection, displays the names of its  objects, and then clears the collection. public void CreatePgSqlParamColl(PgSqlCommand pgCommand) {
  PgSqlParameterCollection myParamCollection = pgCommand.Parameters;
  myParamCollection.Add("DeptNo", PgSqlType.Integer);
  myParamCollection.Add("DName", PgSqlType.VarChar);
  myParamCollection.Add("Loc", PgSqlType.VarChar);
  string myParamNames = "";
  for (int i=0; i < myParamCollection.Count; i++)
    myParamNames += myParamCollection[i].ToString() + "\n";
  MessageBox.Show(myParamNames);
  myParamCollection.Clear();
} Public Sub CreatePgSqlParamColl(pgCommand As PgSqlCommand)
  Dim myParamCollection As PgSqlParameterCollection = pgCommand.Parameters
  myParamCollection.Add("DeptNo", PgSqlType.Integer)
  myParamCollection.Add("DName", PgSqlType.VarChar)
  myParamCollection.Add("Loc", PgSqlType.VarChar)
  Dim myParamNames As String = ""
  Dim i As Integer
  For i = 0 To myParamCollection.Count - 1
    myParamNames += myParamCollection(i).ToString() + ControlChars.Cr
  Next i
  MessageBox.Show(myParamNames)
  myParamCollection.Clear()
End Sub

The following example searches for a  with a given  within a . If the parameter exists, the example displays the name and index of the parameter. If the parameter does not exist, the example displays an error. This example assumes that a  has already been created. public void SearchPgSqlParams() {
  // ...
  // create PgSqlParameterCollection myParameters
  // ...
  if (!myParameters.Contains("DName"))
    MessageBox.Show("ERROR: no such parameter in the collection");
  else
    MessageBox.Show("Name: " + myParameters["DName"].ToString() +
      "Index: " + myParameters.IndexOf("DName").ToString());
} Public Sub SearchPgSqlParams()
  ' ...
  ' create PgSqlParameterCollection myParameters
  ' ...
  If Not myParameters.Contains("DName") Then
    MessageBox.Show("ERROR: no such parameter in the collection")
  Else
    MessageBox.Show("Name: "  & myParameters("DName").ToString()  & _
      "Index: "  & myParameters.IndexOf("DName").ToString())
  End If
End Sub

This sample routine creates and returns  object. public DbConnection GetConnectionBaseClass2(DbProviderFactory factory)
{
// if our factory supports creating a DbConnection, return it.
if ((factory.SupportedClasses & DbProviderSupportedClasses.DbConnection) > 0)
  return factory.CreateConnection();
else
  return null;
} Public Function GetConnectionBaseClass2(ByVal factory As DbProviderFactory) As DbConnection
  'if our factory supports creating a DbConnection, return it.
  If ((factory.SupportedClasses And DbProviderSupportedClasses.DbConnection) > 0) Then
    Return factory.CreateConnection()
  Else
    Return Nothing
  End If
End Function

This sample demonstrates usage of , , , and  classes. It retrieves data from a column of composite type in a table and renders the data to console. To run the samples successfully you have to create server objects with the following script: CREATE TYPE tperson AS (name text, age integer); CREATE TABLE personnel (id integer, person tperson); static void ReadData(PgSqlConnection conn)  
{ 
  string str = "SELECT person FROM personnel"; 
  PgSqlCommand pgCommand = new PgSqlCommand(str,conn); 
  PgSqlDataReader pgReader = pgCommand.ExecuteReader(); 
  while (pgReader.Read())  
  { 
    //obtain data
    PgSqlRow pgRow = pgReader.GetPgSqlRow(0);
    if (pgRow == null) 
    {
      Console.WriteLine();
      continue;
    }
    //obtain data description
    PgSqlRowType pgRowType = pgRow.RowType;
    //iterate through all columns
    foreach(PgSqlAttribute pgAttr in pgRowType.Attributes)
    {
      Console.Write(pgRow[pgAttr] + "\t"); 
    }
    Console.WriteLine();
  } 
  pgReader.Close(); 
} Sub ReadData(ByVal conn As PgSqlConnection)
  Dim str As String = "SELECT person FROM personnel"
  Dim pgCommand As PgSqlCommand = New PgSqlCommand(str, conn)
  Dim pgReader As PgSqlDataReader = pgCommand.ExecuteReader()
  While pgReader.Read()
    'obtain data
    Dim pgRow As PgSqlRow = pgReader.GetPgSqlRow(0)
    If pgRow Is Nothing Then
      Console.WriteLine()
    Else
      'obtain data description
      Dim pgRowType As PgSqlRowType = pgRow.RowType
      'iterate through all columns
      For Each pgAttr As PgSqlAttribute In pgRowType.Attributes
        Console.Write(pgRow(pgAttr) & Chr(9))
      Next pgAttr
      Console.WriteLine()
    End If
  End While
  pgReader.Close()
End Sub

