The following example creates a PgSqlConnection and a . It also demonstrates how to use the , , and  methods. public static void RunPgSqlTransaction(string myConnString) {
        using (PgSqlConnection pgConnection = new PgSqlConnection(myConnString)) {
                pgConnection.Open();
                // Start a local transaction
                PgSqlTransaction myTrans = pgConnection.BeginTransaction(System.Data.IsolationLevel.ReadCommitted);
                PgSqlCommand pgCommand = pgConnection.CreateCommand();
                try {
                        pgCommand.CommandText = "INSERT INTO Dept(DeptNo, DName) Values(52, 'DEVELOPMENT')";
                        pgCommand.ExecuteNonQuery();
                        pgCommand.CommandText = "INSERT INTO Dept(DeptNo, DName) Values(62, 'PRODUCTION')";
                        pgCommand.ExecuteNonQuery();
                        myTrans.Commit();
                        Console.WriteLine("Both records are written to database.");
                }
                catch (Exception e) {
                        myTrans.Rollback();
                        Console.WriteLine(e.ToString());
                        Console.WriteLine("Neither record was written to database.");
                }
                finally {
                        pgCommand.Dispose();
                        myTrans.Dispose();
                }
    }
} Public Shared Sub RunPgSqlTransaction(myConnString As String)
        Using pgConnection As New PgSqlConnection(myConnString)
                pgConnection.Open()
                ' Start a local transaction
                Dim myTrans As PgSqlTransaction = pgConnection.BeginTransaction(System.Data.IsolationLevel.ReadCommitted)
                Dim pgCommand As PgSqlCommand = pgConnection.CreateCommand()
                Try
                        pgCommand.CommandText = "INSERT INTO Dept(DeptNo, DName) Values(52, 'DEVELOPMENT')"
                        pgCommand.ExecuteNonQuery()
                        pgCommand.CommandText = "INSERT INTO Dept(DeptNo, DName) Values(62, 'PRODUCTION')"
                        pgCommand.ExecuteNonQuery()
                        myTrans.Commit()
                        Console.WriteLine("Both records are written to database.")
                Catch e As Exception
                        myTrans.Rollback()
                        Console.WriteLine(e.ToString())
                        Console.WriteLine("Neither record was written to database.")
                Finally
                        pgCommand.Dispose()
                        myTrans.Dispose()
                End Try
    End Using
End Sub

The following example creates a PgSqlConnection and a . It also demonstrates how to use the , , and  methods. public void RunPgSqlTransaction(string myConnString)
{
  PgSqlConnection pgConnection = new PgSqlConnection(myConnString);
  pgConnection.Open();

  PgSqlCommand pgCommand = new PgSqlCommand();
  PgSqlTransaction myTrans;

  // Start a local transaction
  myTrans = pgConnection.BeginTransaction();
  // Assign transaction object for a pending local transaction
  pgCommand.Transaction = myTrans;

  try
  {
    pgCommand.CommandText = "INSERT INTO Test.Dept(DeptNo, DName) Values(50, 'DEVELOPMENT')";
    pgCommand.ExecuteNonQuery();
    pgCommand.CommandText = "INSERT INTO Test.Dept(DeptNo, DName) Values(60, 'PRODUCTION')";
    pgCommand.ExecuteNonQuery();
    myTrans.Commit();
    Console.WriteLine("Both records are written to database.");
  }
  catch(Exception e)
  {
    myTrans.Rollback();
    Console.WriteLine(e.ToString());
    Console.WriteLine("Neither record was written to database.");
  }
  finally
  {
    pgConnection.Close();
  }
} Public Sub RunPgSqlTransaction(myConnString As String)
  Dim pgConnection As New PgSqlConnection(myConnString)
  pgConnection.Open()

  Dim pgCommand As New PgSqlCommand()
  Dim myTrans As PgSqlTransaction

  ' Start a local transaction
  myTrans = pgConnection.BeginTransaction()
  ' Assign transaction object for a pending local transaction
  pgCommand.Transaction = myTrans

  Try
    pgCommand.CommandText = "INSERT INTO Test.Dept(DeptNo, DName) Values(50, 'DEVELOPMENT')"
    pgCommand.ExecuteNonQuery()
    pgCommand.CommandText = "INSERT INTO Test.Dept(DeptNo, DName) Values(60, 'PRODUCTION')"
    pgCommand.ExecuteNonQuery()
    myTrans.Commit()
    Console.WriteLine("Both records are written to database.")
  Catch e As Exception
    myTrans.Rollback()
    Console.WriteLine(e.ToString())
    Console.WriteLine("Neither record was written to database.")
  Finally
    pgConnection.Close()
  End Try
End Sub

The following example creates a PgSqlConnection and a . It also demonstrates how to use the , , and  methods. public void RunPgSqlTransaction(string myConnString)
{
  PgSqlConnection pgConnection = new PgSqlConnection(myConnString);
  pgConnection.Open();

  PgSqlCommand pgCommand = new PgSqlCommand();
  PgSqlTransaction myTrans;

  // Start a local transaction
  myTrans = pgConnection.BeginTransaction();
  // Assign transaction object for a pending local transaction
  pgCommand.Transaction = myTrans;

  try
  {
    pgCommand.CommandText = "INSERT INTO Test.Dept(DeptNo, DName) Values(50, 'DEVELOPMENT')";
    pgCommand.ExecuteNonQuery();
    pgCommand.CommandText = "INSERT INTO Test.Dept(DeptNo, DName) Values(60, 'PRODUCTION')";
    pgCommand.ExecuteNonQuery();
    myTrans.Commit();
    Console.WriteLine("Both records are written to database.");
  }
  catch(Exception e)
  {
    myTrans.Rollback();
    Console.WriteLine(e.ToString());
    Console.WriteLine("Neither record was written to database.");
  }
  finally
  {
    pgConnection.Close();
  }
} Public Sub RunPgSqlTransaction(myConnString As String)
  Dim pgConnection As New PgSqlConnection(myConnString)
  pgConnection.Open()

  Dim pgCommand As New PgSqlCommand()
  Dim myTrans As PgSqlTransaction

  ' Start a local transaction
  myTrans = pgConnection.BeginTransaction()
  ' Assign transaction object for a pending local transaction
  pgCommand.Transaction = myTrans

  Try
    pgCommand.CommandText = "INSERT INTO Test.Dept(DeptNo, DName) Values(50, 'DEVELOPMENT')"
    pgCommand.ExecuteNonQuery()
    pgCommand.CommandText = "INSERT INTO Test.Dept(DeptNo, DName) Values(60, 'PRODUCTION')"
    pgCommand.ExecuteNonQuery()
    myTrans.Commit()
    Console.WriteLine("Both records are written to database.")
  Catch e As Exception
    myTrans.Rollback()
    Console.WriteLine(e.ToString())
    Console.WriteLine("Neither record was written to database.")
  Finally
    pgConnection.Close()
  End Try
End Sub

The following example shows how to enable SSL data transfer with dotConnect for PostgreSQL. PgSqlConnection conn = new PgSqlConnection("user id=postgres;password=postgres;host=localhost;");
conn.SslOptions.CACert = "E:\\Test\\root.crt";
conn.SslOptions.Cert = "E:\\Test\\client.crt";
conn.SslOptions.Key = "E:\\Test\\client.key";
conn.SslOptions.SslMode = SslMode.Require;
